/*
 * Service worker — caches ONLY the app shell (pages, scripts, styles, icons).
 * Patient data never goes over the network in this app, so nothing sensitive can be cached.
 * Generated by scripts/build-sw.mjs: the version and file list are filled in at build time,
 * so every deploy produces a new worker and phones pick up the update.
 */
const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(VERSION).then((c) => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== VERSION).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

const fromCache = (url) => caches.match(url.pathname, { ignoreSearch: true });

self.addEventListener("fetch", (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== "GET" || url.origin !== self.location.origin) return;

  // Hashed build assets and icons never change: cache first.
  if (url.pathname.startsWith("/_next/static/") || url.pathname.startsWith("/icons/")) {
    event.respondWith(caches.match(req).then((hit) => hit || fetch(req)));
    return;
  }

  // Pages and page data: network first so updates arrive; cached copy when offline.
  event.respondWith(
    fetch(req).catch(() => fromCache(url).then((hit) => hit || (req.mode === "navigate" ? caches.match("/") : Response.error()))),
  );
});
